-- Mom's 70th (trip 6): second copy pass, applied live 2026-09-16.
-- Readability: planning residue removed ("placed before...", "no three-hour
-- wait"), trailing bare map links folded into sentences, titles made parallel,
-- the walk length agreed between stop and logistics, Sunday intro no longer
-- contradicts its own "further north" list.
begin;

-- Thu Oct 15
update koji_stops set body_md = $q$Delta 16, nonstop from Detroit at **6:40pm**, landing at Heathrow **7:10am** Friday. Nathan and Dez land five minutes later; Marshall and Francesca at 10:15am. Friday's first stops cover what happens next.$q$ where id = 487;

-- Fri Oct 16
update koji_stops set body_md = $q$For the 7am landings. Once through immigration (about 8:15), take the Heathrow Express to [Paddington](https://www.google.com/maps/search/?api=1&query=Paddington+Station+London) (15 minutes) and the direct GWR train to [Stroud](https://www.google.com/maps/search/?api=1&query=Stroud+Railway+Station) (about 1h20, roughly hourly), then a 10-minute taxi to the hotel ([01453 767878](tel:+441453767878)). Or pre-book a car from Heathrow to the hotel (about 1h45) and skip the changes. Either way you're at Burleigh Court by midday.$q$ where id = 494;
update koji_stops set body_md = $q$Whoever lands at 10:15 collects the rental at a [Heathrow](https://www.google.com/maps/search/?api=1&query=Heathrow+Airport+car+rental) depot and drives west. About 1h45, and the route skips London. A standard five-seater is enough: it carries the group on day trips and only the driver's luggage, since the others travel by train on the arrival and departure days.$q$ where id = 177;
update koji_stops set body_md = $q$Lunch at [Burleigh Court](https://www.google.com/maps/search/?api=1&query=Burleigh+Court+Brimscombe+Stroud+GL5+2PF) on arrival, or a pub in [Minchinhampton](https://www.google.com/maps/search/?api=1&query=Minchinhampton) or [Nailsworth](https://www.google.com/maps/search/?api=1&query=Nailsworth), both a few minutes from the hotel. [Jolly Nice Farmshop](https://www.google.com/maps/search/?api=1&query=Jolly+Nice+Farmshop+Frampton+Mansell) on the A419 is the quick option on the way in.$q$ where id = 178;
update koji_stops set title = 'Check in at Burleigh Court', body_md = $q$[Burleigh Court](https://www.google.com/maps/search/?api=1&query=Burleigh+Court+Brimscombe+Stroud+GL5+2PF) is a country house hotel at The Roundabouts, Brimscombe, on the hill between Stroud and Minchinhampton. Cirencester is about 20 minutes away; Stow, Bourton, and the Slaughters are 35 to 40 minutes north. Ask about early rooms at lunch. Phone number and sat nav notes are in Logistics.$q$ where id = 179;
update koji_stops set body_md = $q$Dinner at the hotel's [Burleigh Restaurant](https://www.google.com/maps/search/?api=1&query=Burleigh+Court+Brimscombe+Stroud+GL5+2PF) keeps everyone off the road and in bed early on the first night. Two alternatives if there's energy for a drive: [Prithvi](https://www.google.com/maps/search/?api=1&query=Prithvi+Cheltenham) in Cheltenham (about 30 minutes), a Michelin-starred modern Indian restaurant, and [The Woolpack](https://www.google.com/maps/search/?api=1&query=The+Woolpack+Inn+Slad) in Slad (about 15 minutes), the village pub Laurie Lee wrote about and drank in. *Reserve either way.*$q$ where id = 181;

-- Sat Oct 17
update koji_stops set body_md = $q$[Stroud Farmers' Market](https://www.google.com/maps/search/?api=1&query=Stroud+Farmers+Market) runs Saturday mornings from 9, ten minutes from the hotel, and is one of the largest farmers' markets in the country, with dozens of stalls of local produce. Breakfast from the stalls, plus picnic supplies if lunch will be on the green in Lower Slaughter, then drive north (about 50 minutes to Bourton).$q$ where id = 492;
update koji_stops set body_md = $q$About 5.5 miles, mostly flat, on a riverside path along the River Eye. Allow 3 hours with stops. Start in [Bourton-on-the-Water](https://www.google.com/maps/search/?api=1&query=Bourton-on-the-Water) and park at the Rissington Road car park. The loop runs Bourton to Lower Slaughter to Upper Slaughter and back to Bourton; the full route and a shorter version are in Logistics.$q$ where id = 182;
update koji_stops set title = 'Drive to Cirencester', body_md = $q$About 35 minutes. [Cirencester](https://www.google.com/maps/search/?api=1&query=Cirencester) was Corinium, the second-largest town in Roman Britain. Park near the [Market Place](https://www.google.com/maps/search/?api=1&query=Market+Place+Cirencester).$q$ where id = 185;
update koji_stops set body_md = $q$The [Corinium Museum](https://www.google.com/maps/search/?api=1&query=Corinium+Museum+Cirencester) is built around the Roman finds from the town and the villas around it, mosaics above all. About 75 minutes.$q$ where id = 186;
update koji_stops set title = 'Market Place shops and tea' where id = 187;

-- Sun Oct 18
update koji_stops set body_md = $q$An open day; nearest options first.<br><br>**Harry Potter locations:** [Gloucester Cathedral](https://www.google.com/maps/search/?api=1&query=Gloucester+Cathedral) (25 minutes) is the Hogwarts corridors from the first three films, with fan-vaulted cloisters, and has choral evensong on Sunday afternoons (check the time). [Lacock Abbey](https://www.google.com/maps/search/?api=1&query=Lacock+Abbey+Wiltshire) (40 minutes, National Trust) is the Mirror of Erised room and more corridors, in a village that doubled as Budleigh Babberton and the Potters' Godric's Hollow house.<br><br>**Close by:** the [Woolpack](https://www.google.com/maps/search/?api=1&query=The+Woolpack+Inn+Slad) in Slad (15 minutes) and the Laurie Lee Way up the valley, hilly and uneven; [Tetbury](https://www.google.com/maps/search/?api=1&query=Tetbury) (20 minutes) for breakfast at [Charlie's Cafe](https://www.google.com/maps/search/?api=1&query=Charlies+Cafe+and+Wine+Bar+Tetbury), [Top Banana Antiques](https://www.google.com/maps/search/?api=1&query=Top+Banana+Antiques+Tetbury), and [Highgrove Gardens](https://www.google.com/maps/search/?api=1&query=Highgrove+Gardens+Tetbury) tours if any dates remain (book weeks ahead); [Malmesbury Abbey](https://www.google.com/maps/search/?api=1&query=Malmesbury+Abbey) (25 minutes), burial place of Athelstan; afternoon tea at [Lords of the Manor](https://www.google.com/maps/search/?api=1&query=Lords+of+the+Manor+Upper+Slaughter) in Upper Slaughter; [Sudeley Castle](https://www.google.com/maps/search/?api=1&query=Sudeley+Castle+Winchcombe) (45 minutes), Katherine Parr's burial place, with some of the finest gardens in the region; dinner at [Lardon](https://www.google.com/maps/search/?api=1&query=Lardon+Elkstone) in Elkstone, wood-fired cooking 25 minutes from the hotel.<br><br>**October colour:** [Westonbirt, the National Arboretum](https://www.google.com/maps/search/?api=1&query=Westonbirt+Arboretum) (20 minutes), at its peak in late October, and [Painswick Rococo Garden](https://www.google.com/maps/search/?api=1&query=Painswick+Rococo+Garden) (15 minutes).<br><br>**Further north, an hour or more each way:** [Broadway Tower](https://www.google.com/maps/search/?api=1&query=Broadway+Tower+Worcestershire), [Chipping Campden](https://www.google.com/maps/search/?api=1&query=Chipping+Campden) and [Hidcote](https://www.google.com/maps/search/?api=1&query=Hidcote+Manor+Garden), [Batsford Arboretum](https://www.google.com/maps/search/?api=1&query=Batsford+Arboretum+Moreton-in-Marsh), [Blenheim Palace](https://www.google.com/maps/search/?api=1&query=Blenheim+Palace+Woodstock), [Bibury](https://www.google.com/maps/search/?api=1&query=Bibury).<br><br>Many village kitchens close on Sunday night, so book dinner ahead: [The Wild Rabbit](https://www.google.com/maps/search/?api=1&query=The+Wild+Rabbit+Kingham), [The Old Butcher's](https://www.google.com/maps/search/?api=1&query=The+Old+Butchers+Stow+on+the+Wold), Lardon, or the hotel.$q$ where id = 477;

-- Mon Oct 19
update koji_stops set body_md = $q$Check out. Some of the group take a 10-minute taxi to [Stroud](https://www.google.com/maps/search/?api=1&query=Stroud+Railway+Station) and the direct train to [Paddington](https://www.google.com/maps/search/?api=1&query=Paddington+Station+London) (about 1h20); the rest return the car at Heathrow, where it was collected, and take the Heathrow Express to Paddington (15 minutes). No driving in London. Everyone at Paddington by about 1pm. The flat is a 10-minute walk, but check-in is 3pm, so bags go to the left-luggage counter at Paddington or come along to lunch.$q$ where id = 488;

-- Tue Oct 20
update koji_stops set body_md = $q$The coronation church since 1066 and the burial place of monarchs, with Gothic vaulting and Poets' Corner. About 90 minutes; wander first, then turn on the audio guide. Book the first timed slot at [Westminster Abbey](https://www.google.com/maps/search/?api=1&query=Westminster+Abbey+London) (9:30 to 10:00), the quietest of the day; tickets go on sale weeks ahead. [Westminster Pier](https://www.google.com/maps/search/?api=1&query=Westminster+Pier+London), where the boat leaves, is a 5-minute walk.$q$ where id = 144;
update koji_stops set body_md = $q$Lunch at [Greenwich Market](https://www.google.com/maps/search/?api=1&query=Greenwich+Market+London), a covered market under a Victorian glass roof with craft stalls and food from a dozen or more cuisines. Most stalls are closed Mondays, which is why Greenwich is Tuesday.$q$ where id = 172;
update koji_stops set body_md = $q$Forty thousand square feet of painted ceiling and walls by James Thornhill, completed over 19 years in the early 1700s, in the dining hall of what was the Royal Hospital for Seamen. About 45 minutes at the [Old Royal Naval College](https://www.google.com/maps/search/?api=1&query=Old+Royal+Naval+College+Greenwich).$q$ where id = 171;
update koji_stops set body_md = $q$The [Cutty Sark](https://www.google.com/maps/search/?api=1&query=Cutty+Sark+Greenwich+London) is a 19th-century tea clipper, once the fastest ship on the China tea run, dry-docked next to the pier and open to walk through. Thirty minutes, and easy to skip if anyone is tired. Last entry is 4:15, which is why it comes before the Observatory. The free [National Maritime Museum](https://www.google.com/maps/search/?api=1&query=National+Maritime+Museum+Greenwich) is the wet-weather alternative.$q$ where id = 174;
update koji_stops set body_md = $q$The Prime Meridian runs through the courtyard of the [Royal Observatory](https://www.google.com/maps/search/?api=1&query=Royal+Observatory+Greenwich+London); stand with a foot in each hemisphere. The walk up through [Greenwich Park](https://www.google.com/maps/search/?api=1&query=Greenwich+Park+London) takes about 10 minutes and is steep at the end; the top looks back over the river to the City. Closes at 5.$q$ where id = 173;

-- Wed Oct 21
update koji_stops set body_md = $q$[Kew Gardens](https://www.google.com/maps/search/?api=1&query=Kew+Gardens+London) is a UNESCO World Heritage site with the largest botanical collection in the world, 30 minutes by Tube from Lancaster Gate (Central line to Notting Hill Gate, then the District line to Kew Gardens). The [Palm House](https://www.google.com/maps/search/?api=1&query=Palm+House+Kew+Gardens) is a Victorian glasshouse from 1848, the [Temperate House](https://www.google.com/maps/search/?api=1&query=Temperate+House+Kew+Gardens) is the largest surviving Victorian glasshouse anywhere, and the [Treetop Walkway](https://www.google.com/maps/search/?api=1&query=Treetop+Walkway+Kew+Gardens) runs 18 metres up through the canopy. October means dahlias and autumn colour. Three hours from the 10am opening covers it; bring a layer. Timed entry, so book ahead.$q$ where id = 164;
update koji_stops set body_md = $q$Free, no tickets, and a straight run from Kew on the District line (about 25 minutes). The [V&A](https://www.google.com/maps/search/?api=1&query=Victoria+and+Albert+Museum+London) holds the world's largest collection of decorative arts and design. The fashion and textile galleries connect to Saturday's Liberty stop; the Cast Courts (full-size plaster casts of Trajan's Column and Michelangelo's David) and the jewellery rooms are the other rooms to see. An hour or two. Anyone who would rather rest goes straight back to the flat from Kew.$q$ where id = 491;
update koji_stops set title = 'Portobello Road', body_md = $q$Pastel terraces, antiques shops, [Honest Jon's](https://www.google.com/maps/search/?api=1&query=Honest+Jons+Records+Portobello+London) records (a shop here since 1974), and the painted houses on [Lancaster Road](https://www.google.com/maps/search/?api=1&query=Lancaster+Road+Notting+Hill+London). Start at the south end of [Portobello Road](https://www.google.com/maps/search/?api=1&query=Portobello+Road+Notting+Hill+London) and walk up. The antiques market runs on Saturdays; a weekday visit is quieter.$q$ where id = 167;
update koji_stops set body_md = $q$[The Churchill Arms](https://www.google.com/maps/search/?api=1&query=The+Churchill+Arms+Notting+Hill+London) is a pub covered in flower baskets, named for Churchill, whose grandparents drank here, with a Thai kitchen in the back that has served food since 1988. Dinner is here unless the group prefers one of the alternatives below; arrive by 6:30 for a table. For a cocktail first, [Trailer Happiness](https://www.google.com/maps/search/?api=1&query=Trailer+Happiness+Portobello+London) down the road is a tiki bar.$q$ where id = 168;

-- Thu Oct 22
update koji_stops set title = 'Split: Sir John Soane''s Museum', body_md = $q$Track one of the morning split. [Sir John Soane's Museum](https://www.google.com/maps/search/?api=1&query=Sir+John+Soanes+Museum+London) is the architect's house, kept as he arranged it under an 1833 Act of Parliament: antiquities, the sarcophagus of Seti I, and Hogarth's A Rake's Progress hung on hinged panels. Free, no tickets; arrive at the 10am opening. About 90 minutes.$q$ where id = 157;
update koji_stops set body_md = $q$Track two. The [Imperial War Museum](https://www.google.com/maps/search/?api=1&query=Imperial+War+Museum+London) in Lambeth is free and open daily 10am-6pm. The [Churchill War Rooms](https://www.google.com/maps/search/?api=1&query=Churchill+War+Rooms+London), the underground bunker the war cabinet worked from, is the alternative (timed tickets; book ahead). Everyone meets at [The Lamb](https://www.google.com/maps/search/?api=1&query=The+Lamb+Lambs+Conduit+Street+London) for lunch at 12:30.$q$ where id = 484;
update koji_stops set body_md = $q$Track three. The Northern line runs to [Hampstead](https://www.google.com/maps/search/?api=1&query=Hampstead+London) in about 30 minutes from Lancaster Gate; the village sits on the hill above Hampstead Heath. Coffee at [Gail's](https://www.google.com/maps/search/?api=1&query=Gails+Bakery+Hampstead), the original branch, then the [Antique & Craft Emporium](https://www.google.com/maps/search/?api=1&query=Hampstead+Antique+and+Craft+Emporium) and [St John-at-Hampstead](https://www.google.com/maps/search/?api=1&query=St+John+at+Hampstead+Church), whose churchyard holds John Constable's grave. Back down to Bloomsbury for 12:30 (25 minutes).$q$ where id = 493;
update koji_stops set title = 'Lunch at The Lamb', body_md = $q$[The Lamb](https://www.google.com/maps/search/?api=1&query=The+Lamb+Lambs+Conduit+Street+London) is a Victorian pub on Lamb's Conduit Street with its etched-glass "snob screens" still in place, a short walk from the museums. Order the pies. Lamb's Conduit Street itself, a Georgian street of independent shops, is worth ten minutes before or after.$q$ where id = 159;
update koji_stops set body_md = $q$Free, no tickets. One room at the [British Library](https://www.google.com/maps/search/?api=1&query=British+Library+London) with Magna Carta, the Lindisfarne Gospels, handwritten Beatles lyrics, and Jane Austen's manuscripts. About 45 minutes. From there it is 10 minutes along the canal to [Word on the Water](https://www.google.com/maps/search/?api=1&query=Word+on+the+Water+Kings+Cross), a bookshop on a 1920s Dutch barge.$q$ where id = 160;
update koji_stops set body_md = $q$[Daunt Books](https://www.google.com/maps/search/?api=1&query=Daunt+Books+Marylebone+London) is an Edwardian bookshop with oak galleries and a skylight, where the books are shelved by country rather than by subject. About 30 minutes. From the British Library it is a 25-minute walk or a short Tube ride.$q$ where id = 161;
update koji_stops set body_md = $q$Five minutes from Daunt. Afternoon tea in the glass-roofed courtyard of Hertford House, the 1776 townhouse that holds the [Wallace Collection](https://www.google.com/maps/search/?api=1&query=The+Wallace+Collection+London) of 18th-century French art and armour. Less expensive than the Ritz or Claridge's. Book about 4 weeks out and confirm a 4:30 sitting exists, since the museum closes at 5; if not, tea first at 3:30 and Daunt after.$q$ where id = 162;

-- Fri Oct 23
update koji_stops set body_md = $q$The Yeoman Warder ("Beefeater") tours at the [Tower of London](https://www.google.com/maps/search/?api=1&query=Tower+of+London) leave every 30 minutes from inside the gate and are included with admission: an hour of stories at an easy pace. See the Crown Jewels straight after, before the queue builds. Book the 9am opening slot.$q$ where id = 150;
update koji_stops set body_md = $q$Ten minutes on foot across [Tower Bridge](https://www.google.com/maps/search/?api=1&query=Tower+Bridge+London), with views of the Tower and up the river from the middle. The paid glass-floor walkway is skippable.$q$ where id = 151;
update koji_stops set body_md = $q$[Borough Market](https://www.google.com/maps/search/?api=1&query=Borough+Market+London) is London's oldest food market, trading on this site since the 13th century. Lunch works stall by stall rather than as one sit-down: [Bread Ahead](https://www.google.com/maps/search/?api=1&query=Bread+Ahead+Borough+Market+London) doughnuts, [Padella](https://www.google.com/maps/search/?api=1&query=Padella+Borough+Market+London) pasta (if the line is short), a [Kappacasein](https://www.google.com/maps/search/?api=1&query=Kappacasein+Borough+Market+London) cheese toastie, oysters from [Richard Haward's](https://www.google.com/maps/search/?api=1&query=Richard+Hawards+Oysters+Borough+Market+London), a family that has farmed oysters in Essex for seven generations. Eat outside by [Southwark Cathedral](https://www.google.com/maps/search/?api=1&query=Southwark+Cathedral+London). Allow 90 minutes. This is the big meal of the day, so dinner is kept casual.$q$ where id = 152;
update koji_stops set body_md = $q$Wren's [St Paul's](https://www.google.com/maps/search/?api=1&query=St+Pauls+Cathedral+London), finished in 1710 after the Great Fire. The Whispering Gallery is 257 steps up and the Golden Gallery at the top is 528; nobody has to do the whole climb. Wellington and Nelson are in the crypt. About an hour.$q$ where id = 153;
update koji_stops set body_md = $q$A 15-minute walk from St Paul's. [Leadenhall Market](https://www.google.com/maps/search/?api=1&query=Leadenhall+Market+London) is a Victorian arcade of iron and glass from 1881, on the site of the Roman forum; it stood in for Diagon Alley in the first Harry Potter film. Fifteen minutes is enough.$q$ where id = 154;

-- Sat Oct 24
update koji_stops set body_md = $q$[Liberty](https://www.google.com/maps/search/?api=1&query=Liberty+London+Great+Marlborough+Street) is a Tudor-revival department store on Great Marlborough Street, built in the 1920s from the timbers of two decommissioned warships, HMS Impregnable and HMS Hindustan. The Liberty print fabrics and the haberdashery floor are the reason for the stop; the rest of the store is open to wander. No booking; open into the evening.$q$ where id = 489;

-- Logistics
update koji_logistics set value_md = $q$**5.4 mi · ~3 hrs · easy.** Park at the Pay & Display car park on Rissington Road, [Bourton-on-the-Water](https://www.google.com/maps/search/?api=1&query=Rissington+Road+Bourton-on-the-Water+car+park) (~£5 / 4hrs). Follow Warden's Way signs north. Bourton → [Lower Slaughter](https://www.google.com/maps/search/?api=1&query=Lower+Slaughter) (1.5mi, riverside) → [Upper Slaughter](https://www.google.com/maps/search/?api=1&query=Upper+Slaughter) (0.7mi through fields) → back via the southern footpath. Mid-walk stop at [The Slaughters Country Inn](https://www.google.com/maps/search/?api=1&query=The+Slaughters+Country+Inn). Wear waterproof shoes; the path is damp in October.$q$ where id = 31;

commit;

-- Follow-up: the birthday itself is Oct 8, before the trip, so Sketch is
-- "the celebratory option" rather than "for the birthday itself"; the Book
-- Ahead rows carry real deadlines and dates instead of lead times.
begin;
update koji_stops set body_md = $q$**British:** [The Guinea Grill](https://www.google.com/maps/search/?api=1&query=The+Guinea+Grill+Mayfair+London), a Mayfair pub dating to the 1600s, known for dry-aged British beef and its steak and kidney pie. *Reservation required.*<br><br>**Indian:** [Kricket Soho](https://www.google.com/maps/search/?api=1&query=Kricket+Soho+London), small plates and a tandoor, with walk-ins at the bar before 7pm. *Reservation recommended.*<br><br>**Modern European:** [Sketch (The Glade)](https://www.google.com/maps/search/?api=1&query=Sketch+Mayfair+London), the forest-themed dining room at Sketch in Mayfair; the celebratory option for the birthday trip. *Reservation required; book now.*$q$ where id = 149;
update koji_logistics set label = 'Book now', value_md = $q$These sell out or book up a month ahead, so they need doing this week: [Westminster Abbey](https://www.google.com/maps/search/?api=1&query=Westminster+Abbey+London) timed entry (Tue Oct 20, 9:30) · [Tower of London](https://www.google.com/maps/search/?api=1&query=Tower+of+London) 9am slot (Fri Oct 23) · [Warner Bros. Studio Tour](https://www.google.com/maps/search/?api=1&query=Warner+Bros+Studio+Tour+London+Leavesden) 10:30 slot (Sat Oct 24) · [Wallace Collection](https://www.google.com/maps/search/?api=1&query=The+Wallace+Collection+London) afternoon tea (Thu Oct 22) · [Sketch](https://www.google.com/maps/search/?api=1&query=Sketch+Mayfair+London) (Mon Oct 19) · [St. John Bread and Wine](https://www.google.com/maps/search/?api=1&query=St+John+Bread+and+Wine+Spitalfields+London) (Fri Oct 23) · [Akoko](https://www.google.com/maps/search/?api=1&query=Akoko+Fitzrovia+London) (Wed Oct 21, may already be full). All for a party of five.$q$ where id = 36;
update koji_logistics set label = 'Book by Oct 1', value_md = $q$[Burleigh Court](https://www.google.com/maps/search/?api=1&query=Burleigh+Court+Brimscombe+Stroud+GL5+2PF) dinner (Fri Oct 16) · [Mousetrap Inn](https://www.google.com/maps/search/?api=1&query=The+Mousetrap+Inn+Bourton+on+the+Water) lunch (Sat Oct 17) · [Bell at Sapperton](https://www.google.com/maps/search/?api=1&query=The+Bell+at+Sapperton), [Wheatsheaf Northleach](https://www.google.com/maps/search/?api=1&query=The+Wheatsheaf+Inn+Northleach) or [Prithvi](https://www.google.com/maps/search/?api=1&query=Prithvi+Cheltenham) (Sat Oct 17) · [Wild Rabbit](https://www.google.com/maps/search/?api=1&query=The+Wild+Rabbit+Kingham), [Old Butcher's](https://www.google.com/maps/search/?api=1&query=The+Old+Butchers+Stow+on+the+Wold) or Lardon (Sun Oct 18) · [Guinea Grill](https://www.google.com/maps/search/?api=1&query=The+Guinea+Grill+Mayfair+London) or [Kricket Soho](https://www.google.com/maps/search/?api=1&query=Kricket+Soho+London) (Mon Oct 19) · [Adulis](https://www.google.com/maps/search/?api=1&query=Adulis+Restaurant+Vauxhall+London) (Tue Oct 20) · [Trishna](https://www.google.com/maps/search/?api=1&query=Trishna+Marylebone+London) (Thu Oct 22) · [Brigadiers](https://www.google.com/maps/search/?api=1&query=Brigadiers+Restaurant+London) (Fri Oct 23) · final dinner (Sat Oct 24, still to choose)$q$ where id = 37;
commit;
